<?php $page_title='Products';require 'includes/header.php';
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$a=$_POST['action']??'';if($a==='save'){ $id=(int)$_POST['id'];$vals=[trim($_POST['name']),trim($_POST['description']),(int)$_POST['category_id'],(float)$_POST['price'],max(0,min(100,(float)$_POST['discount'])),max(0,(int)$_POST['stock']),max(0,min(5,(float)$_POST['rating'])),max(0,(int)$_POST['review_count']),trim($_POST['main_image']),$_POST['status']];if($id){$pdo->prepare("UPDATE products SET name=?,description=?,category_id=?,price=?,discount=?,stock=?,rating=?,review_count=?,main_image=?,status=? WHERE id=?")->execute([...$vals,$id]);flash('success','Product updated successfully.');}else{$pdo->prepare("INSERT INTO products(name,description,category_id,price,discount,stock,rating,review_count,main_image,status) VALUES(?,?,?,?,?,?,?,?,?,?)")->execute($vals);flash('success','Product added successfully.');}header('Location: products.php');exit;}if($a==='delete'){ $id=(int)$_POST['id'];$pdo->prepare("DELETE FROM products WHERE id=?")->execute([$id]);flash('success','Product deleted safely.');header('Location: products.php');exit;}if($a==='toggle'){ $id=(int)$_POST['id'];$pdo->prepare("UPDATE products SET status=IF(status='active','inactive','active') WHERE id=?")->execute([$id]);header('Location: products.php');exit;}}
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare("SELECT * FROM products WHERE id=?");$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}
$cats=$pdo->query("SELECT * FROM categories ORDER BY name")->fetchAll();$products=$pdo->query("SELECT p.*,c.name category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id ORDER BY p.created_at DESC")->fetchAll();?>
<div class="page-head"><div><h1>Products</h1><p>Manage every product in the live catalog.</p></div><a class="btn" href="products.php?edit=0">+ Add product</a></div>
<?php if($edit!==null):?><div class="panel" style="margin-bottom:18px"><h2><?=isset($edit['id'])?'Edit product':'Add product'?></h2><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e((string)($edit['id']??0))?>"><div class="form-grid"><div class="field"><label>Product name</label><input class="input" name="name" value="<?=e($edit['name']??'')?>" required></div><div class="field"><label>Category</label><select name="category_id"><?php foreach($cats as $c):?><option value="<?=$c['id']?>" <?=($c['id']==($edit['category_id']??0)?'selected':'')?>><?=e($c['name'])?></option><?php endforeach;?></select></div></div><div class="field"><label>Description</label><textarea name="description" rows="4" required><?=e($edit['description']??'')?></textarea></div><div class="form-grid"><div class="field"><label>Price</label><input class="input" type="number" step=".01" min="0" name="price" value="<?=e((string)($edit['price']??0))?>" required></div><div class="field"><label>Discount %</label><input class="input" type="number" step=".01" min="0" max="100" name="discount" value="<?=e((string)($edit['discount']??0))?>"></div><div class="field"><label>Stock</label><input class="input" type="number" min="0" name="stock" value="<?=e((string)($edit['stock']??0))?>"></div><div class="field"><label>Rating (0–5)</label><input class="input" type="number" step=".1" min="0" max="5" name="rating" value="<?=e((string)($edit['rating']??0))?>"></div><div class="field"><label>Review count</label><input class="input" type="number" min="0" name="review_count" value="<?=e((string)($edit['review_count']??0))?>"></div><div class="field"><label>Status</label><select name="status"><option value="active" <?=($edit['status']??'active')==='active'?'selected':''?>>Active</option><option value="inactive" <?=($edit['status']??'')==='inactive'?'selected':''?>>Inactive</option></select></div></div><div class="field"><label>Main image URL/path (optional)</label><input class="input" name="main_image" value="<?=e($edit['main_image']??'')?>"></div><button class="btn">Save product</button> <a class="btn light" href="products.php">Cancel</a></form></div><?php endif;?>
<div class="panel"><div class="table-wrap"><table><tr><th>ID</th><th>Product</th><th>Category</th><th>Price</th><th>Stock</th><th>Status</th><th>Actions</th></tr><?php foreach($products as $p):?><tr><td>#<?=$p['id']?></td><td><div style="display:flex;align-items:center;gap:10px"><div style="width:48px;height:48px;border-radius:8px;overflow:hidden;background:#eee;flex:none"><?php if($p['main_image']): ?><img src="../<?=e($p['main_image'])?>" alt="" style="width:100%;height:100%;object-fit:cover"><?php endif; ?></div><div><strong><?=e($p['name'])?></strong><br><small><?=$p['rating']?> ★ · <?=$p['review_count']?> reviews</small></div></div></td><td><?=e($p['category_name']??'—')?></td><td><?=money(sale_price($p))?></td><td><?=$p['stock']?></td><td><span class="badge"><?=e($p['status'])?></span></td><td><a class="btn light" href="?edit=<?=$p['id']?>">Edit</a> <form class="inline" method="post" style="display:inline"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$p['id']?>"><button class="btn light">Toggle</button></form> <form class="inline" method="post" style="display:inline"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$p['id']?>"><button class="btn danger" data-confirm="Are you sure you want to delete this product? Existing order history is preserved.">Delete</button></form></td></tr><?php endforeach;?></table></div></div><?php require 'includes/footer.php';?>
